CREATE TABLE IF NOT EXISTS export_jobs(id TEXT PRIMARY KEY,mode TEXT NOT NULL,createdAt INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('QUEUED','RUNNING','COMPLETE','FAILED')),manifestJson TEXT NOT NULL,tableIndex INTEGER NOT NULL DEFAULT 0,cursor INTEGER NOT NULL DEFAULT 0,nextChunk INTEGER NOT NULL DEFAULT 0,rowsExported INTEGER NOT NULL DEFAULT 0,chainHash TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,reason TEXT);
CREATE INDEX IF NOT EXISTS export_queue ON export_jobs(state,createdAt,id);
CREATE TABLE IF NOT EXISTS export_chunks(jobId TEXT NOT NULL REFERENCES export_jobs(id),ordinal INTEGER NOT NULL,content TEXT NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(jobId,ordinal));
